tool_input.new_string:
/* ===== 业务子系统选择页（100% 还原参考稿） ===== */
.systems-screen{background:#f2f4f8}
/* 固定头：iOS 返回箭头 + 居中 16px 粗标题 + 右占位 */
.sys-header{position:fixed;z-index:20;top:var(--status-bar-height,0px);left:0;right:0;margin:0 auto;max-width:720px;height:56px;padding:0 8px;box-sizing:border-box;background:rgba(255,255,255,.8);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);box-shadow:0 1px 8px rgba(0,0,0,.04)}
.sys-header-inner{height:56px;display:flex;align-items:center;justify-content:space-between}
.sys-back,.sys-header-side{width:44px;height:44px;flex-shrink:0;display:flex;align-items:center;justify-content:center}
.sys-back-glyph{display:block;width:11px;height:11px;border-left:2px solid #191c1f;border-bottom:2px solid #191c1f;transform:rotate(45deg)}
.sys-title{flex:1;text-align:center;font-size:16px;font-weight:700;line-height:22px;color:#191c1f}
/* 顶部 Fluent 插画 + 胶囊提示条 */
.system-hero{display:flex;flex-direction:column;align-items:center;padding:16px 16px 20px}
.system-hero-image{width:min(340px,92vw);height:auto}
.sys-prompt{margin-top:12px;display:flex;align-items:center;gap:6px;padding:4px 12px;border-radius:999px;background:rgba(230,232,236,.8);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.sys-prompt-dot{width:6px;height:6px;border-radius:50%;background:#004fd0;animation:sys-pulse 1.6s ease-in-out infinite}
.sys-prompt-text{font-size:12px;line-height:16px;font-weight:500;color:#191c1f}
@keyframes sys-pulse{0%,100%{opacity:1}50%{opacity:.35}}
/* 两列卡片：圆角 16px + 24px 内边距 + 最小 168px 高 */
.system-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:0 16px calc(24px + env(safe-area-inset-bottom))}
.system-card{display:flex;min-height:168px;flex-direction:column;align-items:center;justify-content:center;padding:24px 16px;border-radius:16px;background:#fff;box-sizing:border-box;border:1px solid transparent;transition:transform .2s,box-shadow .2s}
.system-card:active{transform:scale(.97)}
/* 圆角正方形图标容器（56px / radius 16px），四色浅底 + 描边 */
.round-icon{width:56px;height:56px;flex-shrink:0;border-radius:16px;overflow:hidden;display:flex;align-items:center;justify-content:center;border:1px solid transparent;box-sizing:border-box;transition:transform .2s}
.round-icon-image{width:32px;height:32px;object-fit:contain;display:block}
.system-card-title{margin-top:14px;font-size:16px;font-weight:700;line-height:22px;color:#191c1f;letter-spacing:-.2px;text-align:center}
.system-card.disabled{opacity:.55;filter:grayscale(.4);cursor:not-allowed}
/* 四色主题：蓝 / 橙 / 绿 / 紫 */
.system-card.blue{border-color:rgba(224,231,255,.6);box-shadow:0 4px 20px rgba(0,79,208,.05)}
.system-card.blue .round-icon{background:#eff6ff;border-color:#dbeafe;box-shadow:0 2px 8px rgba(37,99,235,.08)}
.system-card.green{border-color:rgba(209,250,229,.6);box-shadow:0 4px 20px rgba(16,185,129,.05)}
.system-card.green .round-icon{background:#ecfdf5;border-color:#a7f3d0;box-shadow:0 2px 8px rgba(5,150,105,.08)}
.system-card.orange{border-color:rgba(254,243,199,.6);box-shadow:0 4px 20px rgba(234,88,12,.05)}
.system-card.orange .round-icon{background:#fff7ed;border-color:#fed7aa;box-shadow:0 2px 8px rgba(234,88,12,.08)}
.system-card.purple{border-color:rgba(237,233,254,.6);box-shadow:0 4px 20px rgba(101,59,201,.05)}
.system-card.purple .round-icon{background:#f5f3ff;border-color:#ddd6fe;box-shadow:0 2px 8px rgba(124,58,237,.08)}
.system-loading{display:flex;align-items:center;justify-content:center;padding:48px 16px}
.system-loading-text{font-size:14px;color:#8a90a2}

