import http.server, urllib.request, socketserver, os

DIST = r"D:\repository\门户H5\dist"
GW = "http://unlimited.b.h5.admin.mobile.v2.fangdichan.shiqu.suzhou.dev.zhi.com"

class Handler(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *a, **kw):
        super().__init__(*a, directory=DIST, **kw)

    def do_POST(self):
        if self.path.startswith("/api/"):
            return self.proxy()
        return super().do_POST()

    def do_GET(self):
        if self.path.startswith("/api/") or self.path.startswith("/zhi2-dev/"):
            return self.proxy()
        return super().do_GET()

    def proxy(self):
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length) if length else None
        req = urllib.request.Request(
            GW + self.path,
            data=body,
            method=self.command,
            headers={
                "Content-Type": self.headers.get("Content-Type", "application/json"),
            },
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = resp.read()
                self.send_response(resp.status)
                ctype = resp.headers.get("Content-Type", "application/json; charset=utf-8")
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)
        except Exception as e:
            self.send_response(502)
            self.end_headers()
            self.wfile.write(str(e).encode("utf-8", "replace"))

    def log_message(self, fmt, *args):
        pass

class Server(socketserver.ThreadingTCPServer):
    allow_reuse_address = True

if __name__ == "__main__":
    print("serving on 8125, proxy ->", GW, flush=True)
    Server(("127.0.0.1", 8125), Handler).serve_forever()

